// Every positive source is constructed below in an explicitly synthetic FIXTURE_ONLY directory.
// No PRODUCT_APPROVED file, participant observation, time sample, approval or production output is manufactured.
internal static class ImportTests
{
    internal static int Run(string sourceRoot,string scratch)
    {
        scratch=Path.GetFullPath(scratch);Sources.CheckNoLinks(scratch);J.Need(!Directory.Exists(scratch),"IMPORT_TEST_OUTPUT_EXISTS");Directory.CreateDirectory(scratch);
        var fixture=new ImportFixture(sourceRoot,Path.Combine(scratch,"fixture-only"));int passed=0;var results=new List<object>();
        void Case(string name,Action action){action();passed++;results.Add(new{name,status="PASS"});Console.WriteLine("PASS "+name);}
        void Reject(string expected,Action action){try{action();}catch(ArgumentException e){J.Need(e.Message.Contains(expected,StringComparison.Ordinal),"TEST_WRONG_REJECTION:"+expected+":"+e.Message);return;}throw new InvalidOperationException("TEST_EXPECTED_REJECTION:"+expected);}
        ImportResult Validate()=>new ProductionImporter(fixture.Root).Validate("request.json",null,null);
        Case("Complete synthetic240 source→fresh proofs→ADR044 readers→typed crossrefs→exact ReleaseLock",()=>{var result=Validate();J.Need(result.Use=="ContractTest"&&result.Player.Count==13,"TEST_FIXTURE_OUTPUT");var texts=J.Parse(result.Player["CampaignText.json"]);J.Need(J.A(texts,"entries").Count==240&&J.S(texts,"approvalStatus")=="FIXTURE_ONLY","TEST_CAMPAIGN_TEXT");var bindings=J.Parse(result.Player["Runtime.bindings.json"]);J.Need(J.A(bindings,"playerFiles").Count==12&&J.A(bindings,"playerFiles").All(p=>J.Raw(result.Player[J.S(p,"path")])==J.H(p,"rawSha256")),"TEST_RUNTIME_RAW_BINDINGS");result.Write(Path.Combine(scratch,"projected-fixture"));J.Need(!Directory.GetFiles(Path.Combine(scratch,"projected-fixture","player"),"*",SearchOption.AllDirectories).Any(p=>p.Contains("proof",StringComparison.OrdinalIgnoreCase)||p.Contains("solution",StringComparison.OrdinalIgnoreCase)||p.Contains("evidence",StringComparison.OrdinalIgnoreCase)),"TEST_PLAYER_AUTHORING_LEAK");});
        Case("Repeat projection byte identity and exact original float manifest bytes",()=>{var a=Validate();var b=Validate();J.Need(a.Player.All(x=>b.Player[x.Key].SequenceEqual(x.Value))&&a.Player["RailwayAssets.json"].SequenceEqual(File.ReadAllBytes(Path.Combine(fixture.Root,"railway.json"))),"TEST_NONDETERMINISTIC_OR_FLOAT_CANONICALIZED");});
        void Mutate(string name,string path,Func<JsonValue,JsonValue> change,string code){Case(name,()=>{byte[] old=fixture.Read(path);fixture.Write(path,change(J.Parse(old)));try{Reject(code,()=>Validate());}finally{fixture.WriteBytes(path,old);}});}
        Mutate("Candidate DRAFT source cannot reach new calibrated import","campaign.json",v=>J.Put(v,"approvalStatus",J.Str("DRAFT")),"CATALOG");
        Mutate("Null threshold is rejected with no default","levels/S1-01-01-01.json",v=>J.Put(v,"production",J.Put(J.Get(v,"production"),"starThresholdsSeconds",JsonValue.Null)),"NOT_CALIBRATED");
        Mutate("Rehashed calibration cannot replace target full document hash","calibration.json",v=>J.Put(v,"campaign",J.Arr(J.A(v,"campaign").Select((r,i)=>i==0?J.Put(r,"sourceDocumentSha256",J.Str(new string('a',64))):r))),"LEVEL_CALIBRATION_BINDING");
        Mutate("Rewards have no caller fallback","campaign-completion.json",v=>J.Put(v,"completionCatalog",J.Put(J.Get(v,"completionCatalog"),"rewardDefinitions",J.Arr(J.A(J.Get(v,"completionCatalog"),"rewardDefinitions").Select((r,i)=>i==0?J.Put(r,"amountPatience",J.Num(16)):r)))),"STAR_REWARDS_INVALID");
        Mutate("Actual P06 cosmetic price cannot be changed by a catalog selfhash","cosmetics.json",v=>J.Put(v,"items",J.Arr(J.A(v,"items").Select((c,i)=>J.S(c,"id")=="train-anschlusswunder"?J.Put(c,"pricePatience",J.Num(1)):c))),"P06_COSMETIC_VALUES_CHANGED");
        Mutate("Unresolved player localization blocks output","localization.json",v=>J.Put(v,"entries",J.Arr(J.A(v,"entries").Where(e=>J.S(e,"key")!="level.s1.01.01.01.title"))),"PLAYER_TEXT_UNRESOLVED");
        Case("Completion map kind cannot silently fall back",()=>{byte[] old=fixture.Read("railway.json");string text=Encoding.UTF8.GetString(old);int first=text.IndexOf("\"kind\": \"MAP\"",StringComparison.Ordinal);fixture.WriteBytes("railway.json",Encoding.UTF8.GetBytes(text.Remove(first,13).Insert(first,"\"kind\": \"TRAIN\"")));try{Reject("TYPED_MOMENT_UNRESOLVED",()=>Validate());}finally{fixture.WriteBytes("railway.json",old);}});
        Case("Asset fractional coordinates are never accepted by integer-JCS",()=>Reject("IMPORT_JSON",()=>J.Parse(fixture.Read("railway.json"))));
        Case("Duplicate keys in float asset source are rejected",()=>{byte[] old=fixture.Read("railway.json");fixture.WriteBytes("railway.json",Encoding.UTF8.GetBytes(Encoding.UTF8.GetString(old).Replace("\"rendererVersion\":","\"schemaVersion\":1,\"rendererVersion\":")));try{Reject("DUPLICATE_KEY",()=>Validate());}finally{fixture.WriteBytes("railway.json",old);}});
        Mutate("ReleaseLock cannot omit a quality source","release-lock.json",v=>J.Put(v,"catalogHashes",J.Arr(J.A(v,"catalogHashes").Skip(1))),"LOCK_CATALOG_SET");
        Mutate("ReleaseLock full target doc remains exact","release-lock.json",v=>J.Put(v,"puzzles",J.Arr(J.A(v,"puzzles").Select((r,i)=>i==0?J.Put(r,"documentSha256",J.Str(new string('a',64))):r))),"LOCK_PUZZLE_BINDING");
        Case("Trust cannot come from use bool or self-declared status",()=>{byte[] old=fixture.Read("request.json");fixture.Write("request.json",J.Put(J.Parse(old),"use",J.Str("Production")));try{Reject("TRUSTED_APPROVAL_SOURCE_REQUIRED",()=>Validate());}finally{fixture.WriteBytes("request.json",old);}});
        Mutate("Unknown request fields fail closed","request.json",v=>J.Put(v,"productApproved",JsonValue.FromBoolean(true)),"CLOSED_FIELDS");
        Mutate("Profile unsupported budget is not ignored","profiles/dienstbeginn.json",v=>J.Put(v,"runtimeBudgets",J.Put(J.Get(v,"runtimeBudgets"),"hintBudgetMs",J.Num(101))),"GEN_QUALITY");
        Case("Traversal and output overwrite fail closed",()=>{Reject("SOURCE_PATH",()=>new Sources(fixture.Root).Read("../outside.json"));var r=Validate();Reject("OUTPUT_ALREADY_EXISTS",()=>r.Write(Path.Combine(scratch,"projected-fixture")));});
        Case("Fixture evidence bytes and measured UI references are exact",()=>{byte[] old=fixture.Read("evidence.json");fixture.Write("evidence.json",J.Put(J.Parse(old),"uiSourceSha256",J.Str(new string('b',64))));try{Reject("FIXTURE_EVIDENCE_INVALID",()=>Validate());}finally{fixture.WriteBytes("evidence.json",old);}});
        Case("Production authenticity fails before a self-declared fixture can be treated as approval",()=>{byte[] old=fixture.Read("request.json");fixture.Write("request.json",J.Put(J.Parse(old),"use",J.Str("Production")));try{Reject("TRUSTED_APPROVAL_RAW_MISMATCH",()=>new ProductionImporter(fixture.Root).Validate("request.json","evidence.json",new string('0',64)));Reject("CLOSED_FIELDS",()=>new ProductionImporter(fixture.Root).Validate("request.json","evidence.json",J.Raw(fixture.Read("evidence.json"))));}finally{fixture.WriteBytes("request.json",old);}});
        Case("Fresh proof metrics reject a self-consistently rehashed cache",()=>{byte[] proofOld=fixture.Read("proofs/S1-01-01-01.json"),levelOld=fixture.Read("levels/S1-01-01-01.json");var proof=J.Parse(proofOld);proof=J.Put(proof,"metrics",J.Put(J.Get(proof,"metrics"),"deductionSteps",J.Num(J.N(J.Get(proof,"metrics"),"deductionSteps")+1)));string hash=J.Hash(JsonValue.CreateObject(proof.Members.Where(m=>m.Name!="proofHash")));var ph=J.Obj(("profile",J.Str(LevelHashProfiles.Proof)),("sha256",J.Str(hash)));proof=J.Put(proof,"proofHash",ph);var level=J.Parse(levelOld);level=J.Put(level,"proofRef",J.Put(J.Get(level,"proofRef"),"proofHash",ph));fixture.Write("proofs/S1-01-01-01.json",proof);fixture.Write("levels/S1-01-01-01.json",level);try{Reject("PRF-NONDETERMINISTIC",()=>Validate());}finally{fixture.WriteBytes("proofs/S1-01-01-01.json",proofOld);fixture.WriteBytes("levels/S1-01-01-01.json",levelOld);}});
        Case("Only in-memory metadata promotion with identical float tokens is transferable",()=>{byte[] old=Encoding.UTF8.GetBytes("{\"approvalStatus\":\"DRAFT\",\"scale\":0.5}");byte[] next=Encoding.UTF8.GetBytes("{\"approvalStatus\":\"PRODUCT_APPROVED\",\"scale\":0.5}");UiTransfer.CompareMetadataOnly(old,next,false,null);Reject("RENDER_VALUES_CHANGED",()=>UiTransfer.CompareMetadataOnly(old,Encoding.UTF8.GetBytes("{\"approvalStatus\":\"PRODUCT_APPROVED\",\"scale\":0.50}"),false,null));});
        Case("Metadata transfer cannot change a single player character or lie about source",()=>{string sha=new string('1',64);byte[] old=Encoding.UTF8.GetBytes("{\"approvalStatus\":\"DRAFT\",\"sourceSha256\":\"old\",\"title\":\"A\"}");byte[] next=Encoding.UTF8.GetBytes("{\"approvalStatus\":\"PRODUCT_APPROVED\",\"sourceSha256\":\""+sha+"\",\"title\":\"A\"}");UiTransfer.CompareMetadataOnly(old,next,true,sha);Reject("TARGET_TEXT_SOURCE",()=>UiTransfer.CompareMetadataOnly(old,next,true,new string('2',64)));Reject("RENDER_VALUES_CHANGED",()=>UiTransfer.CompareMetadataOnly(old,Encoding.UTF8.GetBytes(Encoding.UTF8.GetString(next).Replace("\"title\":\"A\"","\"title\":\"B\"")),true,sha));});
